import Foundation
import Testing
@testable import UsageHUD

// Offline fixtures generated by official Zstandard v1.5.7's encoder, with a
// content checksum. Both frames contain compressed blocks, rather than only
// raw blocks. The second omits its uncompressed content-size field.
private let cacheZstdKnownSize = Data(base64Encoded:
    "KLUv/SSF3QIAYoUTGYAnbvBx+N9ntgQUJHVgZAhxcWN7XmpD5owJKkKVUDIwwWp77HtJHkBURAo4Ko/BY1JiXt9svd63xQuR+ua42YEL3MYRfWE4wtqDB0cCAwAgK1BjU8zhDDWULSo="
)!
private let cacheZstdUnknownSize = Data(base64Encoded:
    "KLUv/QQA3QIAYoUTGYAnbvBx+N9ntgQUJHVgZAhxcWN7XmpD5owJKkKVUDIwwWp77HtJHkBURAo4Ko/BY1JiXt9svd63xQuR+ua42YEL3MYRfWE4wtqDB0cCAwAgK1BjU8zhDDWULSo="
)!
private let cacheZstdExpected = Data(
    #"{"five_hour":{"utilization":27,"resets_at":"2026-10-12T18:30:00Z"},"seven_day":{"utilization":63,"resets_at":"2026-10-16T03:00:00Z"}}"#.utf8
)

@Test(arguments: [cacheZstdKnownSize, cacheZstdUnknownSize])
func claudeCacheZstdDecodesRealCompressedBlocks(frame: Data) {
    #expect(ClaudeCacheZstd.decode(frame) == cacheZstdExpected)
    #expect(ClaudeCacheZstd.decode(frame, maximumOutputBytes: cacheZstdExpected.count) == cacheZstdExpected)
    #expect(ClaudeCacheZstd.decode(frame, maximumOutputBytes: cacheZstdExpected.count - 1) == nil)
}

@Test func claudeCacheZstdRejectsTruncatedOrCorruptFrames() {
    for count in 0..<cacheZstdKnownSize.count {
        #expect(ClaudeCacheZstd.decode(Data(cacheZstdKnownSize.prefix(count))) == nil)
    }
    var badChecksum = cacheZstdKnownSize
    badChecksum[badChecksum.count - 1] ^= 1
    #expect(ClaudeCacheZstd.decode(badChecksum) == nil)
    #expect(ClaudeCacheZstd.decode(Data("not a zstd frame".utf8)) == nil)
}

@Test func claudeCacheZstdRejectsMultipleFramesAndTrailingBytes() {
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize + cacheZstdUnknownSize) == nil)
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize + Data([0])) == nil)
    // Zstandard skippable-frame magic and a zero-length payload.
    let skippable = Data([0x50, 0x2A, 0x4D, 0x18, 0, 0, 0, 0])
    #expect(ClaudeCacheZstd.decode(skippable) == nil)
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize + skippable) == nil)
}

@Test func claudeCacheZstdRejectsDictionaryOrExcessiveWindow() {
    var dictionaryFrame = cacheZstdUnknownSize
    // Request a one-byte dictionary ID and add ID=1 after the window field.
    dictionaryFrame[4] |= 1
    dictionaryFrame.insert(1, at: 6)
    #expect(ClaudeCacheZstd.decode(dictionaryFrame) == nil)

    var largeWindow = cacheZstdUnknownSize
    // Window descriptor 0x70 declares a 16 MiB window, beyond the 8 MiB cap.
    largeWindow[5] = 0x70
    #expect(ClaudeCacheZstd.decode(largeWindow) == nil)
    var largestAllowedWindow = cacheZstdUnknownSize
    largestAllowedWindow[5] = 0x68 // 8 MiB
    #expect(ClaudeCacheZstd.decode(largestAllowedWindow) == cacheZstdExpected)
}

@Test func claudeCacheZstdEnforcesFixedAllocationBounds() {
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize, maximumOutputBytes: 0) == nil)
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize, maximumOutputBytes: -1) == nil)
    #expect(ClaudeCacheZstd.decode(cacheZstdKnownSize, maximumOutputBytes: 1_048_577) == nil)
    #expect(ClaudeCacheZstd.decode(Data(repeating: 0, count: ClaudeCacheZstd.maximumInputBytes + 1)) == nil)
}

@Test func claudeCacheZstdCanDecodeAnEmptyStandardFrame() {
    let empty = Data([0x28, 0xB5, 0x2F, 0xFD, 0x20, 0, 1, 0, 0])
    #expect(ClaudeCacheZstd.decode(empty) == Data())
}
